pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 10);
        vm.prank(address(this));
        c.deposit{value: 10}();

        address dummy = address(0xdead);
        c.migrateTo(dummy);

        assertTrue(address(c).balance == 0, "Reference should send full balance");
    }
}
